package com.booklibrary.stacks;

import software.amazon.awscdk.*;
import software.amazon.awscdk.services.apigateway.*;
import software.amazon.awscdk.services.lambda.CfnPermission;
import software.amazon.awscdk.services.lambda.IFunction;
import software.amazon.awscdk.services.logs.*;
import software.constructs.Construct;

import java.nio.file.Path;
import java.util.Map;

/** ApiStack — API Gateway built from the OpenAPI spec generated by the Spring Boot code. */
public class ApiStack extends Stack {

  // Written by OpenApiSpecGeneratorTest during `mvn package` in book-api.
  private static final Path SPEC_FILE = Path.of("..", "book-api", "target", "openapi.json");

  private static final String STAGE_NAME = "prod";
  private static final String API_DESCRIPTION =
      "Book Library REST API — serverless Spring Boot on Lambda";

  private final SpecRestApi restApi;

  public ApiStack(
      final Construct scope,
      final String id,
      final StackProps props,
      final ComputeStack computeStack) {
    super(scope, id, props);

    IFunction lambda = computeStack.getBookApiLambda();

    LogGroup accessLogGroup = createAccessLogGroup();
    Map<String, Object> spec = buildSpec(lambda);

    this.restApi = createRestApi(spec, accessLogGroup);
    allowApiGatewayToInvoke(lambda);
    createOutputs();
  }

  /**
   * CloudWatch log group for API Gateway access logs
   *
   * @return {@link LogGroup}
   */
  private LogGroup createAccessLogGroup() {
    return LogGroup.Builder.create(this, "ApiGatewayAccessLogs")
        .logGroupName("/aws/apigateway/book-library-access-logs")
        .retention(RetentionDays.ONE_MONTH)
        .build();
  }

  /**
   * @param spec {@link Map}
   * @param accessLogGroup {@link LogGroup}
   * @return {@link SpecRestApi}
   */
  private SpecRestApi createRestApi(Map<String, Object> spec, LogGroup accessLogGroup) {
    SpecRestApi api =
        SpecRestApi.Builder.create(this, "BookLibrarySpecApi")
            .restApiName("book-library-api")
            .apiDefinition(ApiDefinition.fromInline(spec))
            .deployOptions(
                StageOptions.builder()
                    .stageName(STAGE_NAME)
                    .metricsEnabled(true)
                    .loggingLevel(MethodLoggingLevel.INFO)
                    .dataTraceEnabled(true)
                    .accessLogDestination(new LogGroupLogDestination(accessLogGroup))
                    .accessLogFormat(AccessLogFormat.jsonWithStandardFields())
                    .build())
            .build();

    // Publish a new deployment whenever the spec changes
    api.getLatestDeployment().addToLogicalId(spec);
    return api;
  }

  /**
   * SpecRestApi doesn't wire up Lambda permissions the way LambdaIntegration does, so grant API
   * Gateway permission to invoke the function. This is created in {@code this} stack on purpose:
   * {@code lambda.addPermission(...)} would put it in ComputeStack and create a cyclic reference.
   *
   * @param lambda {@link IFunction}
   */
  private void allowApiGatewayToInvoke(IFunction lambda) {
    CfnPermission.Builder.create(this, "ApiGatewayInvokeLambda")
        .action("lambda:InvokeFunction")
        .functionName(lambda.getFunctionArn())
        .principal("apigateway.amazonaws.com")
        .sourceArn(restApi.arnForExecuteApi())
        .build();
  }

  private void createOutputs() {
    CfnOutput.Builder.create(this, "ApiGatewayUrl")
        .description("Base URL for the Book Library REST API")
        .value(restApi.getUrl())
        .build();

    CfnOutput.Builder.create(this, "BooksEndpoint")
        .description("Books endpoint")
        .value(restApi.getUrl() + "books")
        .build();
  }

  /**
   * The generated spec with the API Gateway parts added: validators and the Lambda integration.
   *
   * @param lambda {@link IFunction}
   * @return {@link Map}
   */
  private Map<String, Object> buildSpec(IFunction lambda) {
    return ApiGatewaySpec.load(SPEC_FILE)
        .withoutServers()
        .withInfo("book-library-api", API_DESCRIPTION)
        .withRequestValidators()
        .withLambdaIntegration(lambdaInvocationUri(lambda))
        .toMap();
  }

  private String lambdaInvocationUri(IFunction lambda) {
    return String.format(
        "arn:%s:apigateway:%s:lambda:path/2015-03-31/functions/%s/invocations",
        getPartition(), getRegion(), lambda.getFunctionArn());
  }

  public SpecRestApi getRestApi() {
    return restApi;
  }
}
